    """Merge overlapping or touching [start, end] intervals.

    Returns a new list of disjoint intervals sorted by start.
    The input list and its sublists are not modified.
    """
    pairs = sorted((int(interval[0]), int(interval[1])) for interval in intervals)
    merged = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
